"""Meridian CRM 4.2 RBAC permission check migration."""


def can(
    user: dict,
    action: str,
    object: str,
    record: dict,
    role_rows: list[dict],
) -> bool:
    """Return whether *user* may perform *action* on *object* and *record*.

    Matching permission rows are evaluated in their supplied document order.
    A missing matching row denies access.
    """
    role_id = user.get("ROLE_ID", "")

    permission = None
    for row in role_rows:
        if (
            row.get("role_id", "") == role_id
            and row.get("object", "") == object
            and row.get("action", "") == action
        ):
            permission = row
            break

    if permission is None:
        return False

    if action == "DELETE" and record.get("DEL_FLG", "") not in ("", "N"):
        return False

    if role_id == "ADMIN":
        return True

    scope = permission.get("scope", "")

    if scope == "ALL":
        return True
    if scope == "TEAM":
        return user.get("TEAM_CD", "") == record.get("TEAM_CD", "")
    if scope == "OWN":
        return record.get("OWNER_UID", "") == user.get("USR_ID", "")

    return False
